package com.savora.security; import com.savora.model.*; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.util.*;
@Service public class JwtService { @Value("${app.jwt.secret}") String secret; @Value("${app.jwt.access-minutes}") long minutes; public String token(User u){return Jwts.builder().subject(u.email).claim("role",u.role.name()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+minutes*60000)).signWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).compact();} public String email(String t){return Jwts.parser().verifyWith(Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8))).build().parseSignedClaims(t).getPayload().getSubject();} }
